# Extract compact per-test summary: ID, exit, key lines
python3 << 'PY'
import re, pathlib
text = pathlib.Path("/tmp/tls-qa/results.txt").read_text()
blocks = re.split(r"===== ([A-Z]\d+) =====\n", text)
# blocks[0] is preamble, then pairs of (id, body)
results = {}
for i in range(1, len(blocks), 2):
    tid = blocks[i]
    body = blocks[i+1]
    m = re.search(r"exit=(\d+)", body)
    ec = int(m.group(1)) if m else None
    # strip ANSI
    clean = re.sub(r"\x1b\[[0-9;]*m", "", body)
    findings = re.findall(r"\[(CRITICAL|HIGH|MEDIUM|LOW)\][^\n]+", clean)
    stats = None
    for line in clean.splitlines():
        if line.startswith("=== STATS ==="):
            stats = line
    # warnings/errors (first meaningful)
    errs = []
    for line in clean.splitlines():
        low = line.lower()
        if any(k in low for k in ("error", "warning", "invalid", "missing", "no such", "skipping", "no reports", "reports in", "shell")):
            if line.strip() and not line.startswith("CMD:") and "exit=" not in line:
                errs.append(line.strip()[:200])
    results[tid] = {"exit": ec, "findings": findings, "stats": stats, "errs": errs[:6], "body": clean}

# Print summaries in order
order = [f"A{i}" for i in range(1,8)] + [f"B{i}" for i in range(1,7)] + [f"C{i}" for i in range(1,5)] + [f"D{i}" for i in range(1,6)] + [f"E{i}" for i in range(1,6)] + [f"F{i}" for i in range(1,10)] + [f"G{i}" for i in range(1,10)] + [f"H{i}" for i in range(1,12)] + [f"I{i}" for i in range(1,6)]
for tid in order:
    r = results.get(tid)
    if not r:
        print(f"{tid}: MISSING")
        continue
    print(f"\n### {tid} exit={r['exit']}")
    if r['findings']:
        for f in r['findings']:
            print(f"  FINDING: {f}")
    if r['stats']:
        print(f"  {r['stats']}")
    for e in r['errs']:
        print(f"  MSG: {e}")
print(f"\nTotal captured: {len(results)}")
PY
